@extends('admin.layout') @section('title','Tasks') @section('heading','Task Management') @push('styles')<style>.section{margin-bottom:18px}.row{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:center;padding:15px 0;border-bottom:1px solid #eef0f3}.row:last-child{border:0}.meta{font-size:12px;color:#667085;margin-top:4px}.form-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px}.wide{grid-column:1/-1}.status{display:inline-flex;padding:5px 9px;border-radius:99px;background:#eef1ff;color:#4459c5;font-size:11px;font-weight:850}@media(max-width:700px){.row,.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>@endpush @section('content')<section class="card section"><h2>Create new task</h2><form class="form-grid" method="POST" action="{{ route('admin.tasks.store') }}">@csrf<input class="input" name="title" placeholder="Task title" required><select class="input" name="type"><option value="image_resize">Image Resize</option><option value="video_resize">Video Resize</option><option value="image_convert">Image Convert</option></select><input class="input" type="number" step="0.01" min="0" name="reward" placeholder="Reward" required><select class="input" name="slot"><option>morning</option><option>afternoon</option><option>evening</option></select><textarea class="input wide" name="description" placeholder="Task description"></textarea><input type="hidden" name="status" value="available"><button class="btn wide">Create Task</button></form></section><section class="card"><h2>All tasks</h2>@forelse($tasks as $task)<div class="row"><div><strong>{{ $task->title }}</strong><div class="meta">{{ strtoupper(str_replace('_',' ',$task->type)) }} · {{ ucfirst($task->slot) }}</div></div><strong>${{ number_format((float)$task->reward,2) }}</strong><span class="status">{{ ucfirst($task->status) }}</span><form method="POST" action="{{ route('admin.tasks.status',$task) }}">@csrf @method('PATCH')<button class="btn">{{ $task->status==='available'?'Pause':'Activate' }}</button></form></div>@empty<p class="muted">No tasks created yet.</p>@endforelse</section><div style="margin-top:16px">{{ $tasks->links() }}</div>@endsection